<script lang="ts">
	import { browser } from '$app/environment';
	import { apiFetch, ApiError } from '$lib/api/client';
	import type { CatalogPart, CatalogSetDetail, PartCorrection, SetCorrection, SetCorrections } from '$lib/api/types';
	let setNum = $state(''); let metadata = $state<SetCorrection | null>(null); let catalogParts = $state<CatalogPart[]>([]); let partOverrides = $state<PartCorrection[]>([]); let initialEffective = $state<Record<string, unknown>>({}); let error = $state(''); let saving = $state(false); let reason = $state(''); let name = $state(''); let year = $state(''); let theme = $state(''); let numParts = $state(''); let selected = $state<CatalogPart | null>(null); let partQuantity = $state(''); let partSpare = $state(false); let partReason = $state(''); let partOperation = $state<'upsert' | 'delete'>('upsert');
	function fallback(set: CatalogSetDetail): SetCorrection { return { imported: { name: set.name, year: set.year, theme_name: set.theme_name, num_parts: set.num_parts, image_url: set.image_url, external_url: set.external_url, instructions_url: set.instructions_url }, override: null, effective: { name: set.name, year: set.year, theme_name: set.theme_name, num_parts: set.num_parts, image_url: set.image_url, external_url: set.external_url, instructions_url: set.instructions_url }, has_local_overrides: set.has_local_overrides }; }
	function apply(set: CatalogSetDetail, found: SetCorrections | null) { metadata = found?.metadata ?? fallback(set); partOverrides = found?.parts ?? []; const rows = new Map(set.parts.map((row) => [`${row.part_num}:${row.color_id}:${row.is_spare}`, row])); for (const correction of partOverrides) { const row = correction.imported ?? correction.effective; if (row) rows.set(`${row.part_num}:${row.color_id}:${row.is_spare}`, row); } catalogParts = [...rows.values()]; initialEffective = { ...metadata.effective }; name = String(metadata.effective.name ?? ''); year = metadata.effective.year == null ? '' : String(metadata.effective.year); theme = String(metadata.effective.theme_name ?? ''); numParts = String(metadata.effective.num_parts ?? ''); }
	async function load() { if (!setNum.trim()) return; error = ''; metadata = null; try { const set = await apiFetch<CatalogSetDetail>(`/api/catalog/sets/${encodeURIComponent(setNum.trim())}`); const found = await apiFetch<SetCorrections>(`/api/overrides/sets/${encodeURIComponent(setNum.trim())}`).catch((cause) => cause instanceof ApiError && cause.status === 404 ? null : Promise.reject(cause)); apply(set, found); } catch (cause) { error = cause instanceof ApiError ? cause.message : 'Couldn’t load that catalog set.'; } }
	async function save() { if (!metadata || !reason.trim()) { error = 'A correction reason is required.'; return; } const values: Record<string, unknown> = { name: name || null, year: year ? Number(year) : null, theme_name: theme || null, num_parts: numParts ? Number(numParts) : null }; const changes = Object.fromEntries(Object.entries(values).filter(([key, value]) => value !== initialEffective[key])); saving = true; error = ''; try { metadata = await apiFetch<SetCorrection>(`/api/overrides/sets/${encodeURIComponent(setNum.trim())}`, { method: 'PUT', body: { ...changes, reason: reason.trim() } }); initialEffective = { ...metadata.effective }; } catch (cause) { error = cause instanceof ApiError ? cause.message : 'Couldn’t save the correction.'; } finally { saving = false; } }
	function overrideFor(row: CatalogPart) { return partOverrides.find((item) => item.override.part_num === row.part_num && item.override.color_id === row.color_id && item.override.is_spare === row.is_spare); }
	function pairedOverride(row: CatalogPart) { return partOverrides.find((item) => item.override.part_num === row.part_num && item.override.color_id === row.color_id && item.override.is_spare !== row.is_spare && item.override.operation === 'upsert'); }
	function oppositeDelete(row: CatalogPart) { return partOverrides.find((item) => item.override.part_num === row.part_num && item.override.color_id === row.color_id && item.override.is_spare !== row.is_spare && item.override.operation === 'delete'); }
	function editPart(row: CatalogPart) { selected = row; const old = overrideFor(row); const paired = pairedOverride(row); partOperation = paired?.override.operation ?? old?.override.operation ?? 'upsert'; partQuantity = String(paired?.override.quantity ?? old?.override.quantity ?? row.quantity); partSpare = paired?.override.is_spare ?? old?.override.is_spare ?? row.is_spare; partReason = ''; error = ''; }
	function partUrl(row: CatalogPart) { return `/api/overrides/sets/${encodeURIComponent(setNum.trim())}/parts/${encodeURIComponent(row.part_num)}/${row.color_id}`; }
	async function savePart() { if (!selected || !partReason.trim()) { error = 'A correction reason is required.'; return; } saving = true; try { if (partSpare !== selected.is_spare) { await apiFetch(partUrl(selected), { method: 'PUT', body: { operation: 'delete', quantity: null, is_spare: selected.is_spare, reason: partReason.trim() } }); } await apiFetch(partUrl(selected), { method: 'PUT', body: { operation: partOperation, quantity: partOperation === 'upsert' ? Number(partQuantity) : null, is_spare: partSpare, reason: partReason.trim() } }); selected = null; await load(); } catch (cause) { error = cause instanceof ApiError ? cause.message : 'Couldn’t save the inventory correction.'; } finally { saving = false; } }
	async function removePart() { if (!selected || !partReason.trim()) { error = 'A correction reason is required.'; return; } saving = true; try { const pairedDelete = oppositeDelete(selected); await apiFetch(partUrl(selected), { method: 'DELETE', body: { is_spare: partSpare, reason: partReason.trim() } }); if (partSpare !== selected.is_spare || pairedDelete) await apiFetch(partUrl(selected), { method: 'DELETE', body: { is_spare: partSpare !== selected.is_spare ? selected.is_spare : pairedDelete!.override.is_spare, reason: partReason.trim() } }); selected = null; await load(); } catch (cause) { error = cause instanceof ApiError ? cause.message : 'Couldn’t remove the inventory correction.'; } finally { saving = false; } }
	const metadataFields = [{ key: 'name', label: 'Name' }, { key: 'year', label: 'Year' }, { key: 'theme_name', label: 'Theme' }, { key: 'num_parts', label: 'Part count' }];
	function value(value: unknown) { return value == null ? '—' : String(value); }
	function localValue(key: string) { if (!metadata?.override) return 'none'; return metadata.override[key] == null ? 'inherited' : value(metadata.override[key]); }
	$effect(() => { const requested = browser ? new URLSearchParams(window.location.search).get('set') : null; if (requested) { setNum = requested; void load(); } });
</script>
<section class="panel" aria-labelledby="correction-title"><div><p class="eyebrow">Correction layer</p><h2 id="correction-title">Correct catalog data</h2></div><p class="muted">Imported records remain unchanged. Local corrections take effect in inventory and matching.</p><div class="search"><label>Set number<input placeholder="e.g. 10497-1" bind:value={setNum}/></label><button class="secondary" onclick={() => void load()}>Load set</button></div>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if metadata}<div class="comparison"><div class="metadata"><h3>Imported</h3>{#each metadataFields as field}<p>{field.label}: <strong>Imported: {value(metadata.imported[field.key])}</strong></p>{/each}</div><div class="metadata"><h3>Local override</h3>{#each metadataFields as field}<p>{field.label}: <strong>Local: {localValue(field.key)}</strong></p>{/each}</div><div class="metadata"><h3>Effective</h3>{#each metadataFields as field}<p>{field.label}: <strong>Effective: {value(metadata.effective[field.key])}</strong></p>{/each}</div></div><form class="metadata-form" onsubmit={(event) => { event.preventDefault(); void save(); }}><h3>Edit local correction</h3><label>Name<input bind:value={name}/></label><label>Year<input type="number" bind:value={year}/></label><label>Theme<input bind:value={theme}/></label><label>Parts<input type="number" min="0" bind:value={numParts}/></label><label>Correction reason<input required bind:value={reason}/></label><button class="primary" disabled={saving}>Save correction</button></form><h3>Inventory corrections</h3><div class="rows">{#each catalogParts as row (row.part_num + row.color_id + row.is_spare)}{@const override = overrideFor(row)}<article><div><strong>{row.part_name} · {row.part_num}</strong><p>{#if override?.imported === null}Imported none{:else}Imported quantity {override?.imported?.quantity ?? row.quantity}{/if} · Local {override?.override.operation === 'delete' ? 'delete' : override?.override.quantity ?? 'none'} · Effective quantity {override?.effective?.quantity ?? (override?.override.operation === 'delete' ? 0 : row.quantity)}</p></div><button class="secondary" onclick={() => editPart(row)}>Correct part</button></article>{/each}</div>{#if selected}<form class="part-form" onsubmit={(event) => { event.preventDefault(); void savePart(); }}><h4>Correct {selected.part_name} · {selected.part_num}</h4><label>Operation<select bind:value={partOperation}><option value="upsert">Set effective quantity</option><option value="delete">Remove from effective inventory</option></select></label>{#if partOperation === 'upsert'}<label>Effective quantity<input aria-label="Effective quantity" required type="number" min="1" bind:value={partQuantity}/></label>{/if}<label><input type="checkbox" bind:checked={partSpare}/> Spare part</label><label>Correction reason<input required bind:value={partReason}/></label><button class="primary" disabled={saving}>Save part correction</button>{#if overrideFor(selected) || pairedOverride(selected)}<button type="button" class="danger" disabled={saving} onclick={() => void removePart()}>Remove local correction</button>{/if}<button type="button" class="secondary" onclick={() => selected = null}>Cancel</button></form>{/if}{/if}</section>
<style>.panel{padding:18px;border:1px solid var(--line);background:var(--surface)}h2{margin:0}.eyebrow{margin:0 0 4px;color:var(--red);font-size:.7rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.muted{color:var(--ink-muted);font-size:.84rem}.search{display:flex;gap:8px;align-items:end}.search label,.metadata-form label,.part-form label{display:grid;gap:4px;font-size:.8rem;font-weight:750}.search input,form input,form select{padding:7px;border:1px solid var(--line);background:white}.secondary,.primary,.danger{padding:8px 10px;border:1px solid var(--ink);font-weight:750;cursor:pointer}.secondary{background:var(--surface)}.primary{background:var(--red);color:white}.danger{background:#fff0ef;color:#8b1c28}.comparison{display:grid;grid-template-columns:1fr 1.15fr 1fr;gap:14px;margin-top:16px;padding-top:12px;border-top:1px solid var(--line)}.comparison h3,.panel>h3{margin:18px 0 8px;font-size:.9rem}.metadata-form,.part-form{display:grid;gap:7px}.metadata-form{margin-top:14px;padding-top:12px;border-top:1px solid var(--line)}.rows article{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-top:1px solid var(--line)}.rows p{margin:4px 0;color:var(--ink-muted);font-size:.8rem}.part-form{margin-top:12px;padding:12px;border:1px solid var(--line);background:#f8f5ed}.part-form h4{margin:0}.error{color:#8b1c28;font-size:.84rem}@media(max-width:719px){.comparison{grid-template-columns:1fr}.search{align-items:stretch;flex-direction:column}}</style>
